import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Agentic Context Engineering: Evolving Contexts for Self-Improving Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2510.04618","title":"Agentic Context Engineering: Evolving Contexts for Self-Improving Language Models","archived_date":"2026-05-28T00:00:00.000Z","arxiv_id":2510.04618,"authors":["Qizheng Zhang","Changran Hu","Shubhangi Upasani","Boyuan Ma","Fenglu Hong","Vamsidhar Kamanuru","Jay Rainton","Chen Wu","Mengmeng Ji","Hanchen Li","Urmish Thakker","James Zou","Kunle Olukotun"],"pdf_path":"pdfs/2510.04618.pdf","published_date":"2025-10-06T00:00:00.000Z","venue":"ICLR 2026"},"headers":[],"relativePath":"research/papers/2025-10-06-agentic-context-engineering-2510-04618.md","filePath":"research/papers/2025-10-06-agentic-context-engineering-2510-04618.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-10-06-agentic-context-engineering-2510-04618.md"};function r(s,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="agentic-context-engineering-evolving-contexts-for-self-improving-language-models" tabindex="-1">Agentic Context Engineering: Evolving Contexts for Self-Improving Language Models <a class="header-anchor" href="#agentic-context-engineering-evolving-contexts-for-self-improving-language-models" aria-label="Permalink to &quot;Agentic Context Engineering: Evolving Contexts for Self-Improving Language Models&quot;">​</a></h1><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><blockquote><p>Large language model (LLM) applications such as agents and domain-specific reasoning increasingly rely on context adaptation: modifying inputs with instructions, strategies, or evidence, rather than weight updates. Prior approaches improve usability but often suffer from brevity bias, which drops domain insights for concise summaries, and from context collapse, where iterative rewriting erodes details over time. We introduce ACE (Agentic Context Engineering), a framework that treats contexts as evolving playbooks that accumulate, refine, and organize strategies through a modular process of generation, reflection, and curation. ACE prevents collapse with structured, incremental updates that preserve detailed knowledge and scale with long-context models. Across agent and domain-specific benchmarks, ACE optimizes contexts both offline (e.g., system prompts) and online (e.g., agent memory), consistently outperforming strong baselines: +10.6% on agents and +8.6% on finance, while significantly reducing adaptation latency and rollout cost. Notably, ACE could adapt effectively without labeled supervision and instead by leveraging natural execution feedback. On the AppWorld leaderboard, ACE matches the top-ranked production-level agent on the overall average and surpasses it on the harder test-challenge split, despite using a smaller open-source model. These results show that comprehensive, evolving contexts enable scalable, efficient, and self-improving LLM systems with low overhead.</p></blockquote><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Prior context adaptation methods suffer from two critical failure modes:</p><ol><li><p><strong>Brevity Bias</strong>: Methods prioritize concise instructions, discarding domain-specific heuristics and tactical knowledge essential for complex tasks. Important detail is pruned in favour of summary.</p></li><li><p><strong>Context Collapse</strong>: Monolithic LLM-based rewrites degrade contexts into shorter, less informative summaries over iterations, causing sharp performance declines as accumulated knowledge is overwritten.</p></li></ol><hr><h2 id="method-ace-agentic-context-engineering" tabindex="-1">Method: ACE (Agentic Context Engineering) <a class="header-anchor" href="#method-ace-agentic-context-engineering" aria-label="Permalink to &quot;Method: ACE (Agentic Context Engineering)&quot;">​</a></h2><p>ACE treats LLM contexts as <em>evolving playbooks</em> that accumulate, refine, and organize strategies over time—rather than compressed summaries. The framework employs a modular pipeline of three specialized components:</p><h3 id="three-components" tabindex="-1">Three Components <a class="header-anchor" href="#three-components" aria-label="Permalink to &quot;Three Components&quot;">​</a></h3><ul><li><strong>Generator</strong>: Produces reasoning trajectories and execution traces from task interactions, providing the raw material for insight extraction.</li><li><strong>Reflector</strong>: Analyses Generator outputs to extract concrete, actionable insights from both successes and failures—captures <em>what worked</em>, <em>what failed</em>, and <em>why</em>.</li><li><strong>Curator</strong>: Integrates Reflector insights into the evolving context via structured delta updates, applying deduplication to control growth and maintaining coherent playbook structure.</li></ul><h3 id="three-design-principles" tabindex="-1">Three Design Principles <a class="header-anchor" href="#three-design-principles" aria-label="Permalink to &quot;Three Design Principles&quot;">​</a></h3><p><strong>1. Incremental Delta Updates</strong> Replaces full context rewrites with localized, itemized edits. The Curator produces compact <em>delta contexts</em>—small sets of candidate bullets—that preserve accumulated knowledge while appending new insights. This directly prevents context collapse while reducing computational overhead.</p><p><strong>2. Grow-and-Refine Mechanism</strong> Contexts expand adaptively: new bullets are added for novel insights; existing bullets receive in-place updates (e.g., counter increments for frequency). Semantic deduplication removes redundancy either proactively or lazily when context windows are exceeded. This balances steady expansion with redundancy control.</p><p><strong>3. Modular Workflow</strong> Evaluation, insight extraction, and curation responsibilities are separated across components. This modularity enables each component to be specialized and replaced independently, avoiding the entanglement that causes monolithic rewriters to collapse.</p><h3 id="offline-vs-online-operation" tabindex="-1">Offline vs. Online Operation <a class="header-anchor" href="#offline-vs-online-operation" aria-label="Permalink to &quot;Offline vs. Online Operation&quot;">​</a></h3><ul><li><strong>Offline</strong>: Optimizes static artifacts such as system prompts using historical trajectories before deployment.</li><li><strong>Online</strong>: Maintains agent memory during live task execution, updating the playbook incrementally after each episode.</li></ul><hr><h2 id="experimental-setup" tabindex="-1">Experimental Setup <a class="header-anchor" href="#experimental-setup" aria-label="Permalink to &quot;Experimental Setup&quot;">​</a></h2><p>Benchmarks span two settings:</p><p><strong>Agent tasks:</strong></p><ul><li><strong>AppWorld</strong>: Complex multi-app agent benchmark (the primary agent evaluation); leaderboard comparison against production-level systems.</li></ul><p><strong>Domain-specific reasoning tasks:</strong></p><ul><li><strong>Finance</strong> (FinQA / financial reasoning)</li><li><strong>Medical reasoning</strong></li><li><strong>SQL</strong> (text-to-SQL)</li></ul><p><strong>Baselines:</strong></p><ul><li>GEPA (the primary strong baseline for adaptation latency and rollout comparisons)</li><li>Production-level GPT-4.1 agents (AppWorld leaderboard)</li></ul><p>ACE uses smaller open-source models throughout, demonstrating cost-efficiency relative to production-level closed-source baselines.</p><hr><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><h3 id="agent-tasks-appworld" tabindex="-1">Agent Tasks (AppWorld) <a class="header-anchor" href="#agent-tasks-appworld" aria-label="Permalink to &quot;Agent Tasks (AppWorld)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Result</th></tr></thead><tbody><tr><td>Average improvement over baselines</td><td>+10.6%</td></tr><tr><td>Online adaptation accuracy</td><td>59.5%</td></tr><tr><td>Comparison</td><td>Matches top-ranked production-level GPT-4.1 agent on overall average</td></tr><tr><td>test-challenge split</td><td>Surpasses GPT-4.1 agent despite using smaller open-source model</td></tr></tbody></table><h3 id="domain-specific-tasks" tabindex="-1">Domain-Specific Tasks <a class="header-anchor" href="#domain-specific-tasks" aria-label="Permalink to &quot;Domain-Specific Tasks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Domain</th><th>Improvement</th></tr></thead><tbody><tr><td>Finance</td><td>+8.6%</td></tr><tr><td>Medical reasoning</td><td>+15%</td></tr><tr><td>SQL</td><td>Consistent gains</td></tr></tbody></table><h3 id="efficiency-vs-gepa" tabindex="-1">Efficiency vs. GEPA <a class="header-anchor" href="#efficiency-vs-gepa" aria-label="Permalink to &quot;Efficiency vs. GEPA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Improvement</th></tr></thead><tbody><tr><td>Adaptation latency</td><td>−82.3%</td></tr><tr><td>Rollouts required</td><td>−75.1%</td></tr><tr><td>Evaluation task cost</td><td>−91.5%</td></tr></tbody></table><h3 id="kv-cache-economics" tabindex="-1">KV Cache Economics <a class="header-anchor" href="#kv-cache-economics" aria-label="Permalink to &quot;KV Cache Economics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Input tokens served from KV cache</td><td>91.8%</td></tr><tr><td>Billed cost reduction</td><td>−82.6%</td></tr></tbody></table><h3 id="without-labeled-supervision" tabindex="-1">Without Labeled Supervision <a class="header-anchor" href="#without-labeled-supervision" aria-label="Permalink to &quot;Without Labeled Supervision&quot;">​</a></h3><p>ACE achieves <strong>+14.8% improvement</strong> on agent tasks using only natural execution feedback (no ground-truth labels)—critical for self-improving systems deployed without annotated data.</p><hr><h2 id="ablation-studies" tabindex="-1">Ablation Studies <a class="header-anchor" href="#ablation-studies" aria-label="Permalink to &quot;Ablation Studies&quot;">​</a></h2><p>Key findings from ablation experiments:</p><ul><li><strong>Delta updates are essential</strong>: Removing incremental updates and reverting to full rewrites causes context collapse, with performance degrading sharply over iterations.</li><li><strong>Grow-and-Refine matters</strong>: Disabling semantic deduplication leads to redundant, bloated contexts; disabling growth leads to knowledge staleness.</li><li><strong>Modular separation</strong>: Collapsing Reflector and Curator into a single component degrades extraction quality.</li><li><strong>Reflector quality is the critical dependency</strong>: Weak or adversarial feedback propagated through the Reflector can degrade the playbook.</li></ul><hr><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Framework quality is bounded by the Reflector&#39;s insight extraction capability; poor or adversarial reflection signals degrade the playbook over time.</li><li>Tasks requiring concise instructions (e.g., HotPotQA) benefit less than knowledge-intensive applications demanding detailed domain strategies—ACE&#39;s value scales with task complexity and knowledge depth requirements.</li><li>Not evaluated on tasks where context window constraints are extremely tight.</li></ul><hr><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>ACE demonstrates that treating LLM contexts as <em>evolving, accumulating playbooks</em> rather than compressed summaries enables scalable, efficient, and self-improving LLM systems. The framework achieves production-level agent performance with smaller open-source models by preventing the two core failure modes of prior methods (brevity bias and context collapse) through structured incremental updates and modular generation–reflection–curation pipelines. The approach operates without labeled supervision, making it broadly applicable to real-world deployment scenarios.</p><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Context adaptation ≠ context compression</strong>: Growing a structured playbook outperforms repeatedly rewriting and shrinking it.</li><li><strong>Delta updates prevent collapse</strong>: Small, targeted edits preserve accumulated knowledge better than monolithic rewrites.</li><li><strong>Modularity enables specialization</strong>: Separating generation, reflection, and curation improves each component&#39;s effectiveness.</li><li><strong>KV cache compatibility</strong>: Incremental context structure enables high cache reuse (91.8%), dramatically reducing inference cost.</li><li><strong>Supervision-free adaptation is viable</strong>: Execution feedback alone is sufficient for significant performance gains.</li></ol>',53)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
